import os
import shutil
import json
import ast
from taf.ul.trs_e2e_fw.lib.utils.resource_file import get_resource_file
from taf.ul.trs_e2e_fw.lib.oam.admin.admin_factory import AdminBaseClass
from taf.ul.trs_e2e_fw.lib.oam.exceptions import FailedToGetPnpReport
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from robot.libraries.BuiltIn import BuiltIn

logger = BackgroundLogger.Instance()


class Autoconnection(AdminBaseClass):
    """
    Autoconnection
    """

    def __init__(self):
        super(Autoconnection, self).__init__()

    def clear_and_reset_autoconnection(self, **kwargs):
        """
            * ADMIN *

            *Clear And Reset Auto Connection*
            This keyword does clear and reset of autoconnection process.


            *Parameters:*\n

            | *Arguments* | *Default* | *Comment* | *Config Ref* |
            | timeout | 60 | (Union[int,str]) - Timeout for the operation |  |
            | alias | default | (Union[AdminConnection,str]) Name of execution context |  |
            | dut | bts | (string) - dut |  |

            *Raises:*\n

            *Returns:*\n
                str: Api response
            *Example*

             | Clear And Reset Auto Connection | timeout=30 | alias=default | dut='bts' |

        """
        timeout = kwargs.pop('timeout', 60)
        alias = kwargs.pop('alias', 'default')
        return self.factory.admin.clear_and_reset_auto_connection(timeout=timeout, connection=alias)

    def get_connection_and_configuration_status(self, **kwargs):
        """
            * ADMIN *

            *Get Connection And Configuration Status*
            This keyword checks the status of connection and configuration from admin.


            *Parameters:*\n

            | *Arguments* | *Default* | *Comment* | *Config Ref* |
            | timeout | 60 | (Union[int,str]) - Timeout for the operation |  |
            | alias | default | (Union[AdminConnection,str]) Name of execution context |  |
            | dut | bts | (string) - dut |  |

            *Raises:*\n

            *Returns:*\n
                str: Procedure feedback.
            *Example*

             | Get Connection And Configuration Status | timeout=30 | alias=default | dut='bts' |

        """
        timeout = kwargs.pop('timeout', 60)
        alias = kwargs.pop('alias', 'default')
        return self.factory.admin.get_connection_and_configuration_status(timeout=timeout, connection=alias)

    def set_autoconnection_transport_params(self, **kwargs):
        """
        set_autoconnection_transport_params(*args, **kwargs)
            Set autoconnection transport params.

            Parameters:
                timeout (Union[int,str]) - Timeout for the operation, defaults to 120.
                connection (Union[AdminConnection,str]) - AdminConnection object or if used, string name alias.
                trs_ac_param_file (string) - json file that contains different autoconnection profiles which is placed in resource folder
                trs_ac_profile (string) - profile name to be used, from trs_ac_param_file

            Returns:
                str: status "Succeeded" or "Failed"
        """

        timeout = kwargs.pop('timeout', 120)
        connection = kwargs.pop('alias', 'default')
        param_file = kwargs.pop("trs_ac_param_file", "trs_ac_param.json")
        ac_profile = kwargs['trs_ac_profile']
        base_path = os.path.dirname(BuiltIn().get_variable_value("${SUITE SOURCE}"))
        param_file = os.path.join(base_path, 'resources', param_file)
        list_param = 'ee_subject_alt_names'
        # dictionary to convert keys from ac_profile to camel-cased keys
        ref_keys = {
            "m_plane_ip_address": "mPlaneIpAddress",
            "m_plane_ip_prefix": "mPlaneIpPrefix",
            "default_gateway": "defaultGateway",
            "vlan_id": "vlanId",
            "identification_server_ip_address": "identificationServerIpAddress",
            "ip_sec_ip_address": "ipSecIpAddress",
            "cmp_server_port": "cmpServerPort",
            "cmp_directory": "cmpDirectory",
            "cmp_server_ip_address": "cmpServerIpAddress",
            "ca_subject_name": "caSubjectName",
            "act_cert_validation": "actCertValidation",
            "bts_number_of_san": "btsNumberOfSAN",
            "ee_subject_name": "eeSubjectName",
            "ee_subject_alt_names": "eeSubjectAltNames",
            "act_eap_mode": "actEAPMode",
            "secondary_m_plane_ip_address": "secondaryMPlaneIpAddress",
            "secondary_m_plane_ip_prefix": "secondaryMPlaneIpPrefix",
            "secondary_vlan_id": "secondaryVlanId",
            "subject_alt_name": "subjectAltName",
            "subject_alt_type": "subjectAltType"
        }

        # read the ac_profile from given trs_ac_param json file, situated in resource dir
        # with open(param_file) as json_file:
        #     trs_ac_param = json.load(json_file)["trs_ac_parameters"][ac_profile]
        trs_ac_param = get_resource_file(param_file)
        with open(trs_ac_param) as json_file:
                trs_ac_param = json.load(json_file)["trs_ac_parameters"][ac_profile]
        # convert string to int for integer values
        int_param_list = ["vlanId", "cmpServerPort", "mPlaneIpPrefix", "btsNumberOfSAN", "secondaryMPlaneIpPrefix",
                          "secondaryVlanId"]
        for param in trs_ac_param:
            if param in int_param_list:
                try:
                    if type(trs_ac_param[param]) is str or type(trs_ac_param[param]) is unicode:
                        trs_ac_param[param] = ast.literal_eval(str(trs_ac_param[param]))
                except NameError:
                    try:
                        trs_ac_param[param] = ast.literal_eval(str(trs_ac_param[param]))
                    except Exception as int_e:
                        logger.debug("Reading int value failed: {}.\n.Please pass a proper integer value".format(str(int_e)))

        # convert string to bool for boolean values
        try:
            if type(trs_ac_param["act_cert_validation"]) is str or type(trs_ac_param["act_cert_validation"]) is unicode:
                trs_ac_param["act_cert_validation"] = bool(trs_ac_param["act_cert_validation"])
        except NameError:
            try:
                trs_ac_param["act_cert_validation"] = bool(trs_ac_param["act_cert_validation"])
            except Exception as bool_e:
                logger.debug("Reading act_cert_validation value failed: {}.\n.Please pass a proper bool value".format(str(bool_e)))

        # map other items in the dict to make it camel-case
        new_trs_ac_param = {}
        for key in trs_ac_param:
            new_trs_ac_param[ref_keys[key]] = trs_ac_param[key]

        # for items with a list as value, map their keys (from '_' format to camel-case)
        dict1 = {}
        new_param_list = []
        if list_param in trs_ac_param:
            for i in trs_ac_param[list_param]:
                for key1 in i:
                    dict1[ref_keys[key1]] = i[key1]
                new_param_list.append(dict1)
                dict1 = {}

        # assign the newly created list to its appropriate key
        new_trs_ac_param[ref_keys[list_param]] = new_param_list

        return self.factory.admin.set_autoconnection_transport_params(timeout=timeout, connection=connection, **new_trs_ac_param)

    def get_autoconnection_status(self, **kwargs):

        """
        get_autoconnection_status(*args, **kwargs)
            Get autoconnection status.

        Parameters:
            timeout (Union[int,str]) - Timeout for the operation, defaults to 10
            connection (Union[AdminConnection,str]) - AdminConnection object or if used, string name alias..
        Returns:
            str: autoConnectionStatus parameter of AUTOCONFIG object
        """

        timeout = kwargs.pop('timeout', 10)
        connection = kwargs.pop('alias', 'default')

        return self.factory.admin.get_autoconnection_status(timeout=timeout, connection=connection)

    def get_pnp_report(self, **kwargs):
        """
        get_pnp_report(*args, **kwargs)
            Saves pnp report under given output file name.

        Parameters:
            output_file_name (string) - Path to save report.
            timeout (Union[int,str]) - Timeout for the operation, defaults to 60
            connection (Union[AdminConnection,str]) - AdminConnection object or if used, string name alias..
        Return str:
            Status of the operation or dict response if detailed_output is set to True
        """
        timeout = kwargs.pop('timeout', 10)
        connection = kwargs.pop('alias', 'default')
        output_file_name = kwargs.pop('output_file_name', "pnp_report.txt")

        try:
            get_report_status = self.factory.admin.get_pnp_report(output_file_name=output_file_name, timeout=timeout,
                                                                  connection=connection)
            logger.debug("get_pnp_report return value:: {}".format(str(get_report_status)))
            source_path = os.getcwd()+"/{}".format(output_file_name)
            dest_folder_path = 'execution_logs/'
            if os.path.isfile(source_path):
                shutil.move(source_path, dest_folder_path)

            return dest_folder_path + "/{}".format(output_file_name)

        except Exception as report_e:
            raise FailedToGetPnpReport("Get Pnp Report failed because:{}".format(str(report_e)))

    def change_autoconfiguration_status(self, **kwargs):
        """
        change_autoconfiguration_status(*args, **kwargs)
            Change autoconfiguration status

        Parameters:
            state (string) - autoconfigurationState <Disable | Enable>
            timeout (Union[int,str]) - Timeout for the operation, defaults to 30
            connection (Union[AdminConnection,str]) - AdminConnection object or if used, string name alias..
        Raises:
            ValueError - Raised if provided state is not "Disable" or "Enable"

        Returns:
            str: status "Completed" or "Failed"
        """
        state = kwargs.pop('state', 'Enable')
        timeout = kwargs.pop('timeout', 30)
        connection = kwargs.pop('alias', 'default')

        return self.factory.admin.change_autoconfiguration_status(state=state, timeout=timeout, connection=connection)
